import{R as t,e as a,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Email Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"forms/email-notifications.md","filePath":"forms/email-notifications.md","lastUpdated":1775908585000}'),o={name:"forms/email-notifications.md"};function s(r,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h1><p>Email notifications let a form send email when a submission happens.</p><p>A single form can have multiple notifications, which means one form can often cover several email jobs without needing separate forms for each variation.</p><p>Typical notification patterns include sending a confirmation to the person who submitted the form, sending an internal copy to a team inbox, or sending different messages depending on the answers in the form.</p><p>When you are setting notifications up, most of the work comes down to four things:</p><ul><li>who should receive the email</li><li>when the email should send</li><li>what content should be included</li><li>whether attachments or a PDF should be added</li></ul><h2 id="recipients" tabindex="-1">Recipients <a class="header-anchor" href="#recipients" aria-label="Permalink to &quot;Recipients&quot;">​</a></h2><p>Recipients can be fixed, conditional, or both.</p><p>That means you can often keep one notification and branch the recipients based on form answers, instead of creating a separate notification for every small variation.</p><p>If the email should only send for certain submissions, use <a href="/forms/conditions">Conditions</a>.</p><h2 id="email-content" tabindex="-1">Email content <a class="header-anchor" href="#email-content" aria-label="Permalink to &quot;Email content&quot;">​</a></h2><p>The content editor stays fairly simple on purpose, so the email is more likely to work across mail clients.</p><p>Use the variable picker to insert:</p><ul><li>field values from the submission</li><li>user details, when a logged-in user is involved</li><li>dates and site values</li><li>an “all fields” summary when you want a complete submission overview</li></ul><p>If you need more control over the outer email layout, move that concern into an email template rather than trying to make the content field do everything.</p><h2 id="templates-and-pdfs" tabindex="-1">Templates and PDFs <a class="header-anchor" href="#templates-and-pdfs" aria-label="Permalink to &quot;Templates and PDFs&quot;">​</a></h2><p>A notification can also use:</p><ul><li>an email template to wrap the message</li><li>a PDF template when you want to attach a generated PDF</li></ul><p>That keeps the notification focused on who gets the email and what it should contain, while the template controls presentation.</p><h2 id="preview-and-test-send" tabindex="-1">Preview and test send <a class="header-anchor" href="#preview-and-test-send" aria-label="Permalink to &quot;Preview and test send&quot;">​</a></h2><p>Use the preview tab when you want a quick check of the rendered output with sample content.</p><p>Use a test send when you want to check real delivery, styling, or mail-provider behavior before relying on the notification in production.</p><h2 id="queue-behavior" tabindex="-1">Queue behavior <a class="header-anchor" href="#queue-behavior" aria-label="Permalink to &quot;Queue behavior&quot;">​</a></h2><p>Formie can send notifications through Craft’s queue. That is usually the better choice because it keeps submission requests faster for the person filling out the form.</p><p>If email delivery feels slow or unreliable, check the queue and mailer setup before assuming the notification itself is wrong.</p>',25)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
